(function(){var C={},H=[],crashTimer=null;
function at(t,n){H.push({id:'m'+(Date.now()+(Math.random()*99999|0)),role:t,text:n});C()}
function am(t,n,f,a){H.push({id:'m'+(Date.now()+(Math.random()*99999|0)),role:t,text:n,features:f,ai:a});C()}
function li(){var i='l'+Date.now();H.push({id:i,role:'l'});C();return i}
function ri(i){H=H.filter(function(m){return m.id!==i});C()}
function es(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
function ap(){return window.agentApi||(window.api?window.api.agent:{})||{}}
// Crash recovery monitor
function initCrashMonitor(){var root=document.getElementById('root');if(!root)return;var lastHtml=root.innerHTML;crashTimer=setInterval(function(){try{var r=document.getElementById('root');if(!r||!r.innerHTML||r.innerHTML.trim()===''||r.innerHTML===lastHtml)return;lastHtml=r.innerHTML;if(r.innerHTML.length<50){showCrashRecovery()}}catch(e){}},3000)}
function showCrashRecovery(){if(document.getElementById('crash-banner'))return;var b=document.createElement('div');b.id='crash-banner';b.style.cssText='position:fixed;top:0;left:0;right:0;z-index:99999;background:rgba(239,68,68,.15);border-bottom:1px solid rgba(239,68,68,.3);padding:10px 16px;display:flex;align-items:center;justify-content:center;gap:12px;backdrop-filter:blur(8px)';b.innerHTML='<span style="color:#fca5a5;font-size:13px">应用似乎遇到问题</span><button id="crash-reload" style="background:#ef4444;color:#fff;border:none;border-radius:6px;padding:6px 14px;font-size:12px;cursor:pointer">重新加载</button><button id="crash-dismiss" style="background:transparent;color:#94a3b8;border:1px solid #475569;border-radius:6px;padding:6px 14px;font-size:12px;cursor:pointer">忽略</button>';document.body.insertBefore(b,document.body.firstChild);document.getElementById('crash-reload').onclick=function(){window.location.reload()};document.getElementById('crash-dismiss').onclick=function(){b.remove()}}
var st=document.createElement('style');
st.textContent='.af{position:fixed;bottom:20px;right:20px;z-index:99999;width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,#3b82f6,#8b5cf6);color:#fff;border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 16px rgba(59,130,246,.4);transition:.2s;font-size:18px;font-weight:700}.af:hover{transform:scale(1.1);box-shadow:0 6px 20px rgba(59,130,246,.5)}.ap{position:fixed;bottom:76px;right:20px;z-index:99998;width:360px;max-height:560px;background:#1e293b;border:1px solid #334155;border-radius:14px;box-shadow:0 8px 32px rgba(0,0,0,.5);display:none;flex-direction:column;overflow:hidden}.ap.o{display:flex}.ah{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid #334155;background:linear-gradient(135deg,#1e293b,#0f172a)}.aht{display:flex;align-items:center;gap:8px;color:#f1f5f9;font-size:14px;font-weight:600}.aht svg{flex-shrink:0}.ahb{display:flex;gap:4px}.ahc{background:none;border:none;color:#64748b;cursor:pointer;padding:4px 8px;border-radius:6px;font-size:14px;transition:.15s}.ahc:hover{color:#f1f5f9;background:rgba(255,255,255,.1)}.at{display:flex;border-bottom:1px solid #334155;padding:4px 12px;gap:4px}.atb{flex:1;padding:6px 0;text-align:center;font-size:12px;color:#64748b;cursor:pointer;border-radius:6px;background:0 0;border:none;transition:.15s}.atb:hover{color:#94a3b8;background:rgba(255,255,255,.05)}.atb.act{color:#60a5fa;background:rgba(59,130,246,.15);font-weight:600}.am{flex:1;overflow-y:auto;padding:12px;min-height:260px;max-height:380px;scrollbar-width:thin;scrollbar-color:#334155 transparent}.am::-webkit-scrollbar{width:4px}.am::-webkit-scrollbar-thumb{background:#334155;border-radius:2px}.ams{margin-bottom:10px;display:flex;animation:afade .2s ease-out}@keyframes afade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}.ams.u{justify-content:flex-end}.ams.a{justify-content:flex-start}.ab{max-width:85%;padding:10px 12px;border-radius:10px;font-size:13px;line-height:1.5;word-break:break-word}.ams.u .ab{background:rgba(59,130,246,.2);border:1px solid rgba(59,130,246,.15);color:#f1f5f9;border-bottom-right-radius:4px}.ams.a .ab{background:rgba(51,65,85,.5);border:1px solid rgba(71,85,105,.25);color:#e2e8f0;border-bottom-left-radius:4px}.fc{margin-top:8px;padding:8px 10px;background:rgba(30,41,59,.8);border-radius:8px;border:1px solid rgba(71,85,105,.3);cursor:pointer;transition:.15s}.fc:hover{border-color:rgba(59,130,246,.3);background:rgba(30,41,59,.9)}.fch{display:flex;justify-content:space-between;align-items:center}.fcn{font-size:13px;font-weight:500;color:#93c5fd}.fcg{font-size:11px;color:#60a5fa;cursor:pointer;padding:2px 6px;border-radius:4px}.fcg:hover{background:rgba(59,130,246,.15)}.fcd{font-size:11px;color:#94a3b8;margin-top:4px}.fcb{margin-top:6px;height:4px;background:#334155;border-radius:2px;overflow:hidden}.fcbf{height:100%;border-radius:2px;transition:width .3s}.fcl{font-size:10px;color:#64748b;text-align:right;margin-top:2px}.ai_{display:flex;gap:8px;padding:12px;border-top:1px solid #334155;background:#0f172a}.ai_i{flex:1;background:#1e293b;border:1px solid #334155;border-radius:8px;padding:8px 12px;color:#f1f5f9;font-size:13px;outline:none;transition:.15s}.ai_i:focus{border-color:#3b82f6}.ai_i::placeholder{color:#475569}.ai_s{background:linear-gradient(135deg,#3b82f6,#8b5cf6);color:#fff;border:none;border-radius:8px;padding:8px 14px;cursor:pointer;font-size:13px;font-weight:500;transition:.15s}.ai_s:disabled{opacity:.4;cursor:not-allowed}.ai_s:hover:not(:disabled){transform:scale(1.05);box-shadow:0 2px 8px rgba(59,130,246,.3)}.em{text-align:center;padding:40px 20px;color:#64748b;font-size:13px;line-height:1.8}.pw{font-size:9px;color:#475569;text-align:right;margin-top:6px}.bdg{display:inline-flex;font-size:9px;font-weight:600;padding:1px 6px;border-radius:4px;margin-bottom:4px}.bdg.ai{background:rgba(139,92,246,.2);color:#a78bfa;border:1px solid rgba(139,92,246,.2)}.bdg.kw{background:rgba(100,116,139,.3);color:#94a3b8;border:1px solid rgba(100,116,139,.2)}';
document.head.appendChild(st);
function build(){
  var p=document.createElement('div');p.className='ap';
  p.innerHTML='<div class="ah"><div class="aht"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" stroke-width="2"><path d="M12 2a8 8 0 0 0-8 8c0 3.5 2 6.5 5 7.8V22l4-4h3a8 8 0 0 0 0-16h-4z"/><path d="M9 10h.01M15 10h.01M12 14c-1.5 0-2.5-.5-3-1"/></svg>AI 助手</div><div class="ahb"><button class="ahc" id="acfg" title="配置">&#x2699;</button><button class="ahc" id="ac" title="关闭">&#x2715;</button></div></div><div class="at"><button class="atb act" data-m="s">&#x1F50D; 搜索功能</button><button class="atb" data-m="c">&#x1F4AC; 自由对话</button></div><div class="am" id="ams"><div class="em" id="emp"><div style="font-size:28px;margin-bottom:10px">&#x1F916;</div>输入关键词搜索功能<br><span style="font-size:11px;color:#475569">例如：重启、备份、Root、刷机</span></div></div><div class="ai_"><input class="ai_i" id="ain" placeholder="搜索功能..."><button class="ai_s" id="asnd">发送</button></div>';
  var b=document.createElement('button');b.className='af';b.textContent='AI';
  document.body.appendChild(b);document.body.appendChild(p);
  var o=false,loading=false,mode='s',mn='';
  b.onclick=function(){o=!o;p.classList.toggle('o',o);if(o)setTimeout(function(){document.getElementById('ain').focus()},150)};
  document.getElementById('ac').onclick=function(){o=false;p.classList.remove('o')};
  document.getElementById('acfg').onclick=function(){cfgD(ap())};
  p.querySelectorAll('.atb').forEach(function(t){t.onclick=function(){p.querySelectorAll('.atb').forEach(function(x){x.classList.remove('act')});t.classList.add('act');mode=t.dataset.m;var i=document.getElementById('ain');i.placeholder=mode==='s'?'搜索功能...':'输入消息...';i.focus()}});
  var inp=document.getElementById('ain'),snd=document.getElementById('asnd');
  snd.onclick=send;inp.onkeydown=function(e){if(e.key==='Enter')send()};inp.oninput=function(){snd.disabled=!inp.value.trim()||loading};
  C=function(){
    var msgs=H.filter(function(m){return m.role!=='l'});
    var c=document.getElementById('ams'),emp=document.getElementById('emp');
    if(msgs.length===0){emp.style.display='';return}
    emp.style.display='none';c.querySelectorAll('.ams').forEach(function(e){e.remove()});
    msgs.forEach(function(msg){
      var d=document.createElement('div');d.className='ams '+msg.role.charAt(0);
      var h='<div class="ab">';
      if(msg.features&&msg.features.length>0)h+='<span class="bdg '+(msg.ai?'ai':'kw')+'">'+(msg.ai?'AI':'关键词')+'</span>';
      h+='<div>'+es(msg.text)+'</div>';
      if(msg.features&&msg.features.length>0)msg.features.forEach(function(f){h+='<div class="fc"><div class="fch"><span class="fcn">'+es(f.name)+'</span><span class="fcg" data-p="'+f.path+'">前往 &#x276F;</span></div><div class="fcd">'+es(f.explanation||'')+'</div><div class="fcb"><div class="fcbf" style="width:'+f.confidence+'%;background:'+(f.confidence>=70?'#22c55e':f.confidence>=40?'#eab308':'#64748b')+'"></div></div><div class="fcl">'+f.confidence+'% 匹配</div></div>'});
      if(msg.role==='a'&&msg.ai&&mn)h+='<div class="pw">Powered by '+es(mn)+'</div>';
      h+='</div>';d.innerHTML=h;c.appendChild(d);
      d.querySelectorAll('.fcg').forEach(function(a){a.onclick=function(e){e.preventDefault();window.location.hash=a.dataset.p;o=false;p.classList.remove('o')}});
    });
    c.scrollTop=c.scrollHeight;
  };
  function send(){
    var t=inp.value.trim();if(!t||loading)return;
    inp.value='';snd.disabled=true;loading=true;
    at('user',t);var ld=li();var a=ap();
    if(mode==='s'){
      (a.search?a.search(t):Promise.resolve({matches:[]})).then(function(r){
        ri(ld);if(r.matches&&r.matches.length>0)am('assistant','找到 '+r.matches.length+' 个相关功能：',r.matches,r.aiPowered);
        else am('assistant','未找到相关功能，请尝试其他关键词。',[],false);
        loading=false;snd.disabled=false;
      }).catch(function(){ri(ld);am('assistant','查询失败，请重试。',[],false);loading=false;snd.disabled=false});
    }else{
      var ms=H.filter(function(m){return m.role!=='l'}).map(function(m){return{role:m.role==='user'?'user':'assistant',content:m.text}});
      ms.push({role:'user',content:t});
      (a.chat?a.chat(ms):Promise.resolve({reply:'AI 未配置，请点击齿轮按钮配置 API。'})).then(function(r){
        ri(ld);am('assistant',r.reply||'',[],false);loading=false;snd.disabled=false;
      }).catch(function(){ri(ld);am('assistant','对话失败，请检查 API 配置。',[],false);loading=false;snd.disabled=false});
    }
  }
  var a=ap();if(a.getConfig)a.getConfig().then(function(c){mn=c.model||''}).catch(function(){});
  initCrashMonitor();
}
function cfgD(a){
  a.getConfig().then(function(cfg){
    var bg=document.createElement('div');
    bg.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.6);z-index:999999;display:flex;align-items:center;justify-content:center;animation:afade .2s';
    var d=document.createElement('div');
    d.style.cssText='background:#1e293b;border:1px solid #334155;border-radius:14px;padding:24px;width:340px;color:#f1f5f9;font-size:13px;box-shadow:0 16px 48px rgba(0,0,0,.5)';
    d.innerHTML='<h3 style="margin:0 0 16px;font-size:16px;font-weight:600">AI Agent 配置</h3>'+
      '<label style="display:flex;align-items:center;gap:10px;margin-bottom:14px;font-size:13px;cursor:pointer;padding:8px 12px;background:rgba(59,130,246,.08);border-radius:8px"><input type="checkbox" id="aen"'+(cfg.enabled?' checked':'')+' style="width:16px;height:16px;accent-color:#3b82f6">启用 AI Agent</label>'+
      '<div style="margin-bottom:12px"><label style="display:block;font-size:11px;color:#94a3b8;margin-bottom:4px">API 地址</label><input id="aurl" value="'+es(cfg.apiUrl||'')+'" placeholder="https://api.openai.com/v1" style="width:100%;background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px 10px;color:#f1f5f9;font-size:13px;outline:none;box-sizing:border-box;transition:.15s" onfocus="this.style.borderColor=\'#3b82f6\'" onblur="this.style.borderColor=\'#334155\'"></div>'+
      '<div style="margin-bottom:12px"><label style="display:block;font-size:11px;color:#94a3b8;margin-bottom:4px">API Key</label><input id="akey" type="password" value="'+es(cfg.apiKey||'')+'" placeholder="sk-..." style="width:100%;background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px 10px;color:#f1f5f9;font-size:13px;outline:none;box-sizing:border-box;transition:.15s" onfocus="this.style.borderColor=\'#3b82f6\'" onblur="this.style.borderColor=\'#334155\'"></div>'+
      '<div style="margin-bottom:16px"><label style="display:block;font-size:11px;color:#94a3b8;margin-bottom:4px">模型</label><input id="amdl" value="'+es(cfg.model||'gpt-4o-mini')+'" placeholder="gpt-4o-mini" style="width:100%;background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px 10px;color:#f1f5f9;font-size:13px;outline:none;box-sizing:border-box;transition:.15s" onfocus="this.style.borderColor=\'#3b82f6\'" onblur="this.style.borderColor=\'#334155\'"></div>'+
      '<div style="display:flex;gap:8px">'+
      '<button id="atest" style="flex:1;background:transparent;color:#94a3b8;border:1px solid #475569;border-radius:8px;padding:8px;cursor:pointer;font-size:12px;transition:.15s">测试连接</button>'+
      '<button id="asave" style="flex:1;background:linear-gradient(135deg,#3b82f6,#8b5cf6);color:#fff;border:none;border-radius:8px;padding:8px;cursor:pointer;font-size:12px;font-weight:500;transition:.15s" onmouseover="this.style.opacity=\'0.9\'" onmouseout="this.style.opacity=\'1\'">保存</button>'+
      '<button id="aclose" style="background:#334155;color:#f1f5f9;border:none;border-radius:8px;padding:8px 16px;cursor:pointer;font-size:12px;transition:.15s">取消</button></div>'+
      '<div id="astatus" style="margin-top:10px;font-size:11px;color:#94a3b8;text-align:center"></div>';
    bg.appendChild(d);document.body.appendChild(bg);
    document.getElementById('aclose').onclick=function(){document.body.removeChild(bg)};
    document.getElementById('asave').onclick=function(){
      var e=document.getElementById('aen').checked,u=document.getElementById('aurl').value,k=document.getElementById('akey').value,m=document.getElementById('amdl').value||'gpt-4o-mini';
      a.setConfig({enabled:e,apiUrl:u,apiKey:k,model:m});
      document.getElementById('astatus').textContent='✓ 已保存';document.getElementById('astatus').style.color='#22c55e';
      setTimeout(function(){document.body.removeChild(bg)},1000);
    };
    document.getElementById('atest').onclick=function(){
      var st=document.getElementById('astatus');st.textContent='测试中...';st.style.color='#94a3b8';
      a.testConnection(document.getElementById('aurl').value,document.getElementById('akey').value,document.getElementById('amdl').value||'gpt-4o-mini').then(function(r){
        st.textContent=r.success?'✓ 连接成功：'+r.message:'✗ '+r.message;st.style.color=r.success?'#22c55e':'#ef4444';
      }).catch(function(e){st.textContent='✗ '+e.message;st.style.color='#ef4444'});
    };
  });
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){build()});else build();
})();
